/** autogenerated **/
Ext._define('judicial.pouch.Manage', {
    extend: 'toolkit.widget.TabPanel',

    getPouchGrid: function(cfg) {
        if(!this._grid) {
            this._grid = Ext._create('judicial.pouch.Grid', {
                region: 'north',
                split: true,
                minHeight: 250,
                height: 250
            });

            this._grid.getSelectionModel().on({
                scope: this,
                selectionChange: function(sel) {
                    var selected = sel.getSelections();

                    if(selected.length > 0)
                        this.pouch(selected[0]);
                    else
                        this.pouch(null);
                }
            });
        }

        return this._grid;
    },

    _addItems: function(selection) {
        var rest = Ext._create('judicial.pouch.Restful');
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'adicionando itens...'});

        if(selection.length) {
            mask.show();
            rest.addItems(
                this.pouch().get('pk'),
                selection.map(function(data) { return data.get('pk')}),
                {
                    scope: this,
                    fn: function() {
                        this.getAvailableLawsuitGrid().getStore().reload();
                        this.getSelectedLawsuitGrid().getStore().reload();
                    }
                },
                {
                    fn: function(message) {
                        Ext.Msg.show({
                            title: 'Adicioando itens',
                            msg: message,
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK
                        });
                    }
                },
                {
                    fn: function() { mask.hide(); }
                }
            );
        }
    },

    _removeItems: function(selection) {
        var rest = Ext._create('judicial.pouch.Restful');
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'removendo itens...'});

        if(selection.length) {
            mask.show();
            rest.removeItems(
                this.pouch().get('pk'),
                selection.map(function(data) { return data.get('pk')}),
                {
                    scope: this,
                    fn: function() {
                        this.getAvailableLawsuitGrid().getStore().reload();
                        this.getSelectedLawsuitGrid().getStore().reload();
                    }
                },
                {
                    fn: function(message) {
                        Ext.Msg.show({
                            title: 'Removendo itens',
                            msg: message,
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK
                        });
                    }
                },
                {
                    fn: function() { mask.hide(); }
                }
            );
        }
    },

    addAll: function() {
        this._addItems(this.getAvailableLawsuitGrid().getStore().getRange());
    },

    addAllSelected: function() {
        this._addItems(this.getAvailableLawsuitGrid().getSelectionModel().getSelections());
    },

    removeAll: function() {
        this._removeItems(this.getSelectedLawsuitGrid().getStore().getRange());
    },

    removeAllSelected: function() {
        this._removeItems(this.getSelectedLawsuitGrid().getSelectionModel().getSelections());
    },

    getControlPanel: function(cfg) {
        if(!this._controlPanel)
            this._controlPanel = Ext._create('Ext.Panel', {
                width: 60,
                frame: true,
                border: false,
                layout: {
                    type: 'vbox',
                    align: 'center',
                    pack: 'center',
                    defaultMargins: '5 0'
                },
                defaults: {
                    width: 30,
                    height: 30
                },
                items: [
                    {
                        xtype: 'button',
                        iconCls: 'icon-core icon-core-add-all',
                        scope: this,
                        handler: this.addAll
                    },
                    {
                        xtype: 'button',
                        iconCls: 'icon-core icon-core-add-selected',
                        scope: this,
                        handler: this.addAllSelected
                    },
                    {
                        xtype: 'button',
                        iconCls: 'icon-core icon-core-remove-selected',
                        scope: this,
                        handler: this.removeAllSelected
                    },
                    {
                        xtype: 'button',
                        iconCls: 'icon-core icon-core-remove-all',
                        scope: this,
                        handler: this.removeAll
                    }
                ]
            });

        return this._controlPanel;
    },

    getAvailableLawsuitGrid: function(cfg) {
        if(!this._availableLawsuitGrid)
            this._availableLawsuitGrid = Ext._create('judicial.outcourtlawsuit.OutCourtLawsuitAdminGrid', {
                title: 'Disponiveis',
                configOrderToolBar: ['openDocument', '-', 'search', '->'],
                flex: 1,
                gridAutoLoad: false
            });

        return this._availableLawsuitGrid;
    },

    getSelectedLawsuitGrid: function(cfg) {
        if(!this._selectedLawsuitGrid)
            this._selectedLawsuitGrid = Ext._create('judicial.outcourtlawsuit.OutCourtLawsuitAdminGrid', {
                title: 'No Lote',
                configOrderToolBar: ['openDocument', '-', 'search', '->'],
                flex: 1,
                gridAutoLoad: false
            });

        return this._selectedLawsuitGrid;
    },

    pouch: function(value, dispatch) {
        dispatch = (dispatch === undefined ? true : dispatch);

        if(value !== undefined) {
            this._pouch = value;

            if(dispatch)
                this.pouchObserve();
        }

        return this._pouch;
    },

    pouchObserve: function() {
        var pouch = this.pouch();

        console.log(pouch);

        if(pouch) {
            this.getAvailableLawsuitGrid().setFilterProperty('as_pouches_items__pouch', pouch.get('pk'), -101, false);
            this.getAvailableLawsuitGrid().setFilterProperty('location', pouch.get('from_location'), 101, true);

            this.getSelectedLawsuitGrid().setFilterProperty('as_pouches_items__pouch', pouch.get('pk'), 101);

            this.getAvailableLawsuitGrid().enable();
            this.getSelectedLawsuitGrid().enable();
            this.getControlPanel().enable();
        }
        else {
            this.getAvailableLawsuitGrid().setFilterProperty('as_pouches_items__pouch', 0, -101, false);
            this.getAvailableLawsuitGrid().setFilterProperty('location', 0, 101, true);

            this.getSelectedLawsuitGrid().setFilterProperty('as_pouches_items__pouch', 0, 101);

            this.getAvailableLawsuitGrid().disable();
            this.getSelectedLawsuitGrid().disable();
            this.getControlPanel().disable();
        }
    },

    getContentPanel: function(cfg) {
        if(!this._contentPanel)
            this._contentPanel = Ext._create('Ext.Panel', {
                region: 'center',
                minHeight: 400,
                layout: {
                    type: 'hbox',
                    align: 'stretch'
                },
                items: [
                    this.getAvailableLawsuitGrid(cfg),
                    this.getControlPanel(cfg),
                    this.getSelectedLawsuitGrid(cfg)
                ]
            });

        return this._contentPanel;
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(
            cfg,
            {
                title: 'Gestor de Lote de Movimentação'
            }
        );

        Ext.apply(
            cfg,
            {
                layout: 'border',
                items: [
                    this.getPouchGrid(cfg),
                    this.getContentPanel(cfg)
                ]
            }
        );

        judicial.pouch.Manage.superclass.constructor.call(this, cfg);
        this.pouchObserve();
    }
});
